23	export const load = createAsyncThunk<QueryResults, QueryParams>(
24	    'elements/load',
25	    async (queryParams: QueryParams, { getState, dispatch }) => {
26	        const queryParameters = getQueryElementsParameters(queryParams);
27	        try {
28	            return await queryElements(
29	                queryParams.api,
30	                queryParams.abortController,
31	                queryParams.conversationMode,
32	                queryParameters
33	            );
34	        } catch (error: any | undefined) {
35	            // Wait a couple of seconds before retrying
36	            setTimeout(() => {
37	                const currentRetry = (getState() as RootState).elements.retry;
38	                dispatch(retry(newRetry(currentRetry, queryParameters, error)));
39	            }, 2000);
40	            throw error;
41	        }
42	    }
43	);
