 51	export const loadFulfilled = (
 52	    state: Draft<ElementsState>,
 53	    action: PayloadAction<QueryResults, string, { arg: QueryParams }>
 54	) => {
 55	    const { page, params } = action.meta.arg;
 56	    const { Total, Elements } = action.payload;
 57	
 58	    Object.assign(state, {
 59	        beforeFirstLoad: false,
 60	        invalidated: false,
 61	        pendingRequest: false,
 62	        page,
 63	        total: Total,
 64	        retry: newRetry(state.retry, params, undefined),
 65	    });
 66	    state.pages.push(page);
 67	    Object.assign(state.elements, toMap(Elements, 'ID'));
 68	};
