 70	export const manualPending = (state: Draft<ElementsState>) => {
 71	    state.pendingRequest = true;
 72	};
 73	
 74	export const manualFulfilled = (state: Draft<ElementsState>) => {
 75	    state.pendingRequest = false;
 76	};
 77	
 78	export const removeExpired = (state: Draft<ElementsState>, action: PayloadAction<Element>) => {
 79	    delete state.elements[action.payload.ID || ''];
