 86	export const eventUpdatesPending = (
 87	    state: Draft<ElementsState>,
 88	    action: PayloadAction<undefined, string, { arg: EventUpdates }>
 89	) => {
 90	    const { toCreate, toUpdate, toDelete } = action.meta.arg;
 91	    toCreate.forEach((element) => {
 92	        state.elements[element.ID || ''] = element;
 93	    });
 94	    toUpdate.forEach((element) => {
 95	        const existingElement = state.elements[element.ID || ''];
 96	        if (existingElement) {
 97	            state.elements[element.ID || ''] = parseLabelIDsInEvent(existingElement, element);
 98	        }
 99	    });
100	    toDelete.forEach((elementID) => {
101	        delete state.elements[elementID];
102	    });
103	};
