105	export const eventUpdatesFulfilled = (
106	    state: Draft<ElementsState>,
107	    action: PayloadAction<(Element | undefined)[], string, { arg: EventUpdates }>
108	) => {
109	    action.payload.filter(isTruthy).forEach((element) => {
110	        state.elements[element.ID || ''] = element;
111	    });
112	};
