114	export const addESResults = (state: Draft<ElementsState>, action: PayloadAction<ESResults>) => {
115	    const total = action.payload.elements.length;
116	    const pages = range(0, Math.ceil(total / PAGE_SIZE));
117	    // Retry is disabled for encrypted search results, to avoid re-triggering the search several times
118	    // when there are no results
119	    Object.assign(state, {
120	        bypassFilter: [],
121	        beforeFirstLoad: false,
122	        invalidated: false,
123	        pendingRequest: false,
124	        page: action.payload.page,
125	        total,
126	        pages,
127	        elements: toMap(action.payload.elements, 'ID'),
128	        retry: { payload: undefined, count: MAX_ELEMENT_LIST_LOAD_RETRIES, error: undefined },
129	    });
130	};
