132	export const optimisticUpdates = (state: Draft<ElementsState>, action: PayloadAction<OptimisticUpdates>) => {
133	    action.payload.elements.forEach((element) => {
134	        if (element.ID) {
135	            state.elements[element.ID] = element;
136	        }
137	    });
138	    if (action.payload.isMove) {
139	        const elementIDs = action.payload.elements.map(({ ID }) => ID || '');
140	        state.bypassFilter = diff(state.bypassFilter, elementIDs);
141	    }
142	    if (action.payload.bypass) {
143	        const { conversationMode } = action.payload;
144	        action.payload.elements.forEach((element) => {
145	            const isMessage = testIsMessage(element);
146	            const id = (isMessage && conversationMode ? (element as Message).ConversationID : element.ID) || '';
147	            if (!state.bypassFilter.includes(id)) {
148	                state.bypassFilter.push(id);
149	            }
150	        });
151	    }
152	};
153	
154	export const optimisticDelete = (state: Draft<ElementsState>, action: PayloadAction<OptimisticDelete>) => {
155	    action.payload.elementIDs.forEach((elementID) => {
156	        delete state.elements[elementID];
157	    });
158	};
159	
160	export const optimisticEmptyLabel = (state: Draft<ElementsState>) => {
161	    state.elements = {};
162	    state.page = 0;
163	};

  1	import { useCallback, useEffect, useRef } from 'react';
  2	import { useApi, useCache, useConversationCounts, useMessageCounts } from '@proton/components';
  3	import { omit } from '@proton/shared/lib/helpers/object';
  4	import { ConversationCountsModel, MessageCountsModel } from '@proton/shared/lib/models';
  5	import { LabelCount } from '@proton/shared/lib/interfaces/Label';
  6	import { captureMessage } from '@proton/shared/lib/helpers/sentry';
  7	import { useStore, useDispatch, useSelector } from 'react-redux';
  8	import isTruthy from '@proton/shared/lib/helpers/isTruthy';
  9	import { isSearch } from '../../helpers/elements';
 10	import { Element } from '../../models/element';
 11	import { Filter, Sort, SearchParameters } from '../../models/tools';
 12	import { pageCount } from '../../helpers/paging';
 13	import { useEncryptedSearchContext } from '../../containers/EncryptedSearchProvider';
 14	import { reset, removeExpired, load as loadAction, updatePage } from '../../logic/elements/elementsActions';
 15	import {
 16	    params as paramsSelector,
 17	    elementsMap as elementsMapSelector,
 18	    elements as elementsSelector,
 19	    elementIDs as elementIDsSelector,
 20	    shouldLoadMoreES as shouldLoadMoreESSelector,
 21	    shouldResetCache as shouldResetCacheSelector,
 22	    shouldSendRequest as shouldSendRequestSelector,
 23	    shouldUpdatePage as shouldUpdatePageSelector,
 24	    dynamicTotal as dynamicTotalSelector,
 25	    placeholderCount as placeholderCountSelector,
 26	    loading as loadingSelector,
 27	    totalReturned as totalReturnedSelector,
 28	    expectingEmpty as expectingEmptySelector,
 29	    loadedEmpty as loadedEmptySelector,
 30	    partialESSearch as partialESSearchSelector,
 31	    stateInconsistency as stateInconsistencySelector,
 32	} from '../../logic/elements/elementsSelectors';
 33	import { useElementsEvents } from '../events/useElementsEvents';
 34	import { RootState } from '../../logic/store';
 35	import { useExpirationCheck } from '../useExpiration';
 36	import { conversationByID } from '../../logic/conversations/conversationsSelectors';
 37	import { messageByID } from '../../logic/messages/messagesSelectors';
 38	
 39	interface Options {
 40	    conversationMode: boolean;
 41	    labelID: string;
 42	    page: number;
 43	    sort: Sort;
 44	    filter: Filter;
 45	    search: SearchParameters;
 46	    onPage: (page: number) => void;
 47	}
 48	
 49	interface ReturnValue {
 50	    labelID: string;
 51	    elements: Element[];
 52	    elementIDs: string[];
 53	    placeholderCount: number;
 54	    loading: boolean;
 55	    total: number | undefined;
 56	}
 57	
 58	interface UseElements {
 59	    (options: Options): ReturnValue;
 60	}
 61	
 62	export const useElements: UseElements = ({ conversationMode, labelID, search, page, sort, filter, onPage }) => {
 63	    const store = useStore();
 64	    const dispatch = useDispatch();
 65	
 66	    const api = useApi();
 67	    const abortControllerRef = useRef<AbortController>();
 68	
 69	    const [conversationCounts = [], loadingConversationCounts] = useConversationCounts() as [
 70	        LabelCount[],
 71	        boolean,
 72	        Error
 73	    ];
 74	    const [messageCounts = [], loadingMessageCounts] = useMessageCounts() as [LabelCount[], boolean, Error];
 75	    const countValues = conversationMode ? conversationCounts : messageCounts;
 76	    const countsLoading = conversationMode ? loadingConversationCounts : loadingMessageCounts;
 77	
 78	    const { getESDBStatus } = useEncryptedSearchContext();
 79	    const esDBStatus = getESDBStatus();
 80	    const { esEnabled } = esDBStatus;
 81	
 82	    const globalCache = useCache();
 83	
 84	    const params = { labelID, conversationMode, page, sort, filter, search, esEnabled };
 85	    const counts = { counts: countValues, loading: countsLoading };
 86	
 87	    const stateParams = useSelector(paramsSelector);
 88	    const elementsMap = useSelector(elementsMapSelector);
 89	    const elements = useSelector(elementsSelector);
 90	    const elementIDs = useSelector(elementIDsSelector);
 91	    const shouldLoadMoreES = useSelector((state: RootState) =>
 92	        shouldLoadMoreESSelector(state, { page, search, esDBStatus })
 93	    );
 94	    const shouldResetCache = useSelector((state: RootState) => shouldResetCacheSelector(state, { page, params }));
 95	    const shouldSendRequest = useSelector((state: RootState) => shouldSendRequestSelector(state, { page, params }));
 96	    const shouldUpdatePage = useSelector((state: RootState) => shouldUpdatePageSelector(state, { page }));
 97	    const dynamicTotal = useSelector((state: RootState) => dynamicTotalSelector(state, { counts }));
 98	    const placeholderCount = useSelector((state: RootState) => placeholderCountSelector(state, { counts }));
 99	    const loading = useSelector((state: RootState) => loadingSelector(state));
100	    const totalReturned = useSelector((state: RootState) => totalReturnedSelector(state, { counts }));
101	    const expectingEmpty = useSelector((state: RootState) => expectingEmptySelector(state, { counts }));
102	    const loadedEmpty = useSelector(loadedEmptySelector);
103	    const partialESSearch = useSelector((state: RootState) => partialESSearchSelector(state, { search, esDBStatus }));
104	    const stateInconsistency = useSelector((state: RootState) =>
105	        stateInconsistencySelector(state, { search, esDBStatus })
106	    );
107	
108	    // Remove from cache expired elements
109	    useExpirationCheck(Object.values(elementsMap), (element) => {
110	        dispatch(removeExpired(element));
111	
112	        globalCache.delete(ConversationCountsModel.key);
113	        globalCache.delete(MessageCountsModel.key);
114	    });
115	
116	    // Main effect watching all inputs and responsible to trigger actions on the cache
117	    useEffect(() => {
118	        if (shouldResetCache) {
119	            dispatch(reset({ page, params: { labelID, conversationMode, sort, filter, esEnabled, search } }));
120	        }
121	        if (shouldSendRequest && !isSearch(search)) {
122	            void dispatch(
123	                loadAction({ api, abortController: abortControllerRef.current, conversationMode, page, params })
124	            );
125	        }
126	        if (shouldUpdatePage && !shouldLoadMoreES) {
127	            dispatch(updatePage(page));
128	        }
129	    }, [shouldResetCache, shouldSendRequest, shouldUpdatePage, shouldLoadMoreES, search]);
130	
131	    // Move to the last page if the current one becomes empty
132	    useEffect(() => {
133	        if (page === 0) {
134	            return;
135	        }
136	
137	        if (!partialESSearch && (expectingEmpty || loadedEmpty)) {
138	            const count = dynamicTotal ? pageCount(dynamicTotal) : 0;
139	            if (count === 0) {
140	                onPage(0);
141	            } else if (page !== count - 1) {
142	                onPage(count - 1);
143	            }
144	        }
145	    }, [page, partialESSearch, expectingEmpty, loadedEmpty, dynamicTotal]);
146	
147	    useEffect(() => {
148	        if (stateInconsistency) {
149	            if (!esEnabled) {
150	                const message = 'Elements list inconsistency error';
151	                const state = store.getState();
152	                const context = {
153	                    conversationMode,
154	                    labelID,
155	                    search,
156	                    page,
157	                    sort,
158	                    filter,
159	                    dynamicTotal,
160	                    state: omit(state, ['elements']),
161	                    ...state.elements, // Sentry limit depth in extra data, this optimize our feedback
162	                };
163	                console.error(message, context);
164	                captureMessage(message, { extra: { context } });
165	            }
166	            dispatch(
167	                reset({
168	                    page,
169	                    params: { labelID, sort, filter, esEnabled, search, conversationMode },
170	                    beforeFirstLoad: !esEnabled && isSearch(search),
171	                })
172	            );
173	        }
174	    }, [stateInconsistency]);
175	
176	    useElementsEvents(conversationMode, search);
177	
178	    return {
179	        labelID: stateParams.labelID,
180	        elements,
181	        elementIDs,
182	        placeholderCount,
183	        loading,
184	        total: totalReturned,
185	    };
186	};
