188	/**
189	 * Returns the element in the elements state for the given elementID
190	 */
191	export const useGetElementByID = () => {
192	    const store = useStore<RootState>();
193	
194	    return useCallback((elementID: string): Element | undefined => {
195	        return store.getState().elements.elements[elementID];
196	    }, []);
197	};
