199	/**
200	 * This helper will get as much data as we can on the ids whatever the location of the data
201	 * Don't use this for optimistic for example
202	 */
203	export const useGetElementsFromIDs = () => {
204	    const store = useStore();
205	
206	    return useCallback((elementIDs: string[]): Element[] => {
207	        const state = store.getState();
208	        return elementIDs
209	            .map((ID: string) => {
210	                if (state.elements.elements[ID]) {
211	                    return state.elements.elements[ID];
212	                }
213	
214	                const messageFromMessageState = messageByID(state, { ID });
215	                const conversationFromConversationState = conversationByID(state, { ID });
216	
217	                return messageFromMessageState?.data || conversationFromConversationState?.Conversation;
218	            })
219	            .filter(isTruthy);
220	    }, []);
221	};

  1	import { createSelector } from 'reselect';
  2	import { LabelCount } from '@proton/shared/lib/interfaces';
  3	import isTruthy from '@proton/shared/lib/helpers/isTruthy';
  4	import {
  5	    PAGE_SIZE,
  6	    MAX_ELEMENT_LIST_LOAD_RETRIES,
  7	    ELEMENTS_CACHE_REQUEST_SIZE,
  8	    DEFAULT_PLACEHOLDERS_COUNT,
  9	} from '../../constants';
 10	import { hasLabel, isFilter, isSearch, isUnread, sort as sortElements } from '../../helpers/elements';
 11	import { RootState } from '../store';
 12	import { ElementsStateParams } from './elementsTypes';
 13	import { ESDBStatus } from '../../models/encryptedSearch';
 14	import { getTotal } from './helpers/elementTotal';
 15	import { expectedPageLength } from '../../helpers/paging';
 16	import { SearchParameters } from '../../models/tools';
 17	
 18	const beforeFirstLoad = (state: RootState) => state.elements.beforeFirstLoad;
 19	export const elementsMap = (state: RootState) => state.elements.elements;
 20	export const params = (state: RootState) => state.elements.params;
 21	const page = (state: RootState) => state.elements.page;
 22	const pages = (state: RootState) => state.elements.pages;
 23	const bypassFilter = (state: RootState) => state.elements.bypassFilter;
 24	const pendingRequest = (state: RootState) => state.elements.pendingRequest;
 25	const retry = (state: RootState) => state.elements.retry;
 26	const invalidated = (state: RootState) => state.elements.invalidated;
 27	const total = (state: RootState) => state.elements.total;
 28	
 29	const currentPage = (_: RootState, { page }: { page: number }) => page;
 30	const currentSearch = (_: RootState, { search }: { search: SearchParameters }) => search;
 31	const currentParams = (_: RootState, { params }: { params: ElementsStateParams }) => params;
 32	const currentESDBStatus = (_: RootState, { esDBStatus }: { esDBStatus: ESDBStatus }) => esDBStatus;
 33	const currentCounts = (_: RootState, { counts }: { counts: { counts: LabelCount[]; loading: boolean } }) => counts;
 34	
 35	export const elements = createSelector(
 36	    [elementsMap, params, page, pages, bypassFilter],
 37	    (elements, params, page, pages, bypassFilter) => {
 38	        // Getting all params from the cache and not from scoped params
 39	        // To prevent any desynchronization between cache and the output of the memo
 40	        const { labelID, sort, filter } = params;
 41	
 42	        const minPage = pages.reduce((acc, page) => (page < acc ? page : acc), pages[0]);
 43	        const startIndex = (page - minPage) * PAGE_SIZE;
 44	        const endIndex = startIndex + PAGE_SIZE;
 45	        const elementsArray = Object.values(elements);
 46	        const filtered = elementsArray
 47	            .filter((element) => hasLabel(element, labelID))
 48	            .filter((element) => {
 49	                if (!isFilter(filter)) {
 50	                    return true;
 51	                }
 52	                if (bypassFilter.includes(element.ID || '')) {
 53	                    return true;
 54	                }
 55	                const elementUnread = isUnread(element, labelID);
 56	                return filter.Unread ? elementUnread : !elementUnread;
 57	            });
 58	        const sorted = sortElements(filtered, sort, labelID);
 59	
 60	        return sorted.slice(startIndex, endIndex);
 61	    }
 62	);
 63	
 64	export const elementIDs = createSelector(elements, (elements): string[] =>
 65	    elements.map((element) => element.ID).filter(isTruthy)
 66	);
 67	
 68	export const elementsLength = createSelector(elements, (elements) => elements.length);
 69	
 70	/**
 71	 * Define when we need to request the API to get more elements
 72	 * Dynamic computations (dynamicTotal and dynamicPageLength) have been proved not to be reliable enough
 73	 * So the logic here is a lot more basic
 74	 * It only checks when there is not a full page to show if the label has more than a cache size of elements
 75	 * It doesn't rely at all on the optimistic counter logic
 76	 */
 77	export const needsMoreElements = createSelector([total, page, elementsLength], (total, page, elementsLength) => {
 78	    if (total === undefined) {
 79	        return false;
 80	    }
 81	    const howManyElementsAhead = total - page * PAGE_SIZE;
 82	    return elementsLength < PAGE_SIZE && howManyElementsAhead > ELEMENTS_CACHE_REQUEST_SIZE;
 83	});
 84	
 85	export const paramsChanged = createSelector([params, currentParams], (params, currentParams) => {
 86	    const paramsChanged =
 87	        currentParams.labelID !== params.labelID ||
 88	        currentParams.conversationMode !== params.conversationMode ||
 89	        currentParams.sort !== params.sort ||
 90	        currentParams.filter !== params.filter ||
 91	        currentParams.search !== params.search ||
 92	        (currentParams.esEnabled !== params.esEnabled && isSearch(currentParams.search));
 93	    return paramsChanged;
 94	});
 95	
 96	export const pageCached = createSelector([pages, currentPage], (pages, currentPage) => pages.includes(currentPage));
 97	
 98	export const pageChanged = createSelector([page, currentPage], (page, currentPage) => page !== currentPage);
 99	
100	export const pageIsConsecutive = createSelector(
101	    [pages, currentPage],
102	    (pages, currentPage) =>
103	        pages.length === 0 || pages.some((p) => p === currentPage || p === currentPage - 1 || p === currentPage + 1)
104	);
105	
106	export const shouldResetCache = createSelector(
107	    [paramsChanged, pageIsConsecutive],
108	    (paramsChanged, pageIsConsecutive) => {
109	        return paramsChanged || !pageIsConsecutive;
110	    }
111	);
112	
113	export const shouldSendRequest = createSelector(
114	    [shouldResetCache, pendingRequest, retry, needsMoreElements, invalidated, pageCached],
115	    (shouldResetCache, pendingRequest, retry, needsMoreElements, invalidated, pageCached) => {
116	        return (
117	            shouldResetCache ||
118	            (!pendingRequest &&
119	                retry.count < MAX_ELEMENT_LIST_LOAD_RETRIES &&
120	                (needsMoreElements || invalidated || !pageCached))
121	        );
122	    }
123	);
124	
125	export const isLive = createSelector([params, pages], (params, pages) => !isSearch(params.search) && pages.includes(0));
126	
127	export const shouldUpdatePage = createSelector(
128	    [pageChanged, pageCached],
129	    (pageChanged, pageCached) => pageChanged && pageCached
130	);
131	
132	export const isES = createSelector(
133	    [currentESDBStatus, currentSearch],
134	    ({ dbExists, esEnabled, isCacheLimited }, search) =>
135	        dbExists && esEnabled && isSearch(search) && (!!search.keyword || !isCacheLimited)
136	);
137	
138	export const shouldLoadMoreES = createSelector(
139	    [currentESDBStatus, isES, pageChanged, pageCached],
140	    ({ isCacheLimited, isSearchPartial }, useES, pageChanged, pageCached) =>
141	        useES && isCacheLimited && isSearchPartial && pageChanged && !pageCached
142	);
143	
144	/**
145	 * Computed up to date total of elements for the current parameters
146	 * Warning: this value has been proved not to be 100% consistent
