217	                } finally {
218	                    if (!undoing) {
219	                        start();
220	                        await call();
221	                    }
222	                }
223	                return tokens;
224	            };
225	
226	            // No await ==> optimistic
227	            const promise = handleDo();
228	
229	            const handleUndo = async () => {
230	                try {
231	                    undoing = true;
232	                    const tokens = await promise;
233	                    // Stop the event manager to prevent race conditions
234	                    stop();
235	                    Object.values(rollbacks).forEach((rollback) => rollback());
236	                    const filteredTokens = tokens.filter(isTruthy);
237	                    await Promise.all(filteredTokens.map((token) => api(undoActions(token))));
238	                } finally {
239	                    start();
240	                    await call();
241	                }
242	            };
243	
244	            let notificationText = c('Success').t`Labels applied.`;
245	
246	            const elementsCount = elementIDs.length;
247	
248	            if (changesKeys.length === 1) {
249	                const labelName = labels.filter((l) => l.ID === changesKeys[0])[0]?.Name;
250	
251	                if (changesKeys[0] === MAILBOX_LABEL_IDS.STARRED) {
252	                    notificationText = getNotificationTextStarred(isMessage, elementsCount);
253	                } else if (!Object.values(changes)[0]) {
