258	            }
259	
260	            if (!silent) {
261	                createNotification({
262	                    text: <UndoActionNotification onUndo={handleUndo}>{notificationText}</UndoActionNotification>,
263	                    expiration: SUCCESS_NOTIFICATION_EXPIRATION,
264	                });
265	            }
266	        },
267	        [labels]
268	    );
269	
270	    return applyLabels;
271	};
