13	export const useElementsEvents = (conversationMode: boolean, search: SearchParameters) => {
14	    const api = useApi();
15	    const { getESDBStatus } = useEncryptedSearchContext();
16	    const esDBStatus = getESDBStatus();
17	
18	    const store = useStore<RootState>();
19	    const dispatch = useDispatch();
20	    const isLive = useSelector(isLiveSelector);
21	    const isES = useSelector((state: RootState) => isESSelector(state, { search, esDBStatus }));
22	
23	    // Listen to event manager and update the cache
24	    useSubscribeEventManager(async ({ Conversations = [], Messages = [] }: Event) => {
25	        const Elements: ElementEvent[] = conversationMode ? Conversations : Messages;
26	
27	        // If it's an encrypted search, its event manager will deal with the change
28	        if (isES) {
29	            return;
30	        }
31	
32	        if (!Elements.length) {
33	            return;
34	        }
35	
36	        if (!isLive) {
37	            if (Elements.length) {
38	                dispatch(invalidate());
39	            }
40	            return;
41	        }
42	
43	        const {
44	            toCreate,
45	            toUpdate: toUpdateOrLoad,
46	            toDelete,
47	        } = Elements.reduce<Pick<EventUpdates, 'toCreate' | 'toUpdate' | 'toDelete'>>(
48	            ({ toCreate, toUpdate, toDelete }, event) => {
49	                const { ID, Action } = event;
50	                const Element = conversationMode
51	                    ? (event as ConversationEvent).Conversation
52	                    : (event as MessageEvent).Message;
53	
54	                if (Action === EVENT_ACTIONS.CREATE) {
55	                    toCreate.push(Element as Element);
56	                } else if (Action === EVENT_ACTIONS.UPDATE_DRAFT || Action === EVENT_ACTIONS.UPDATE_FLAGS) {
57	                    toUpdate.push({ ID, ...Element });
58	                } else if (Action === EVENT_ACTIONS.DELETE) {
59	                    toDelete.push(ID);
60	                }
61	
62	                return { toCreate, toUpdate, toDelete };
63	            },
64	            { toCreate: [], toUpdate: [], toDelete: [] }
65	        );
66	
67	        // Not the elements ids "in view" but all in the cache
68	        const elementIDs = Object.keys(store.getState().elements.elements);
69	
70	        const { toUpdate, toLoad } = toUpdateOrLoad
71	            .filter(({ ID = '' }) => !toDelete.includes(ID)) // No need to get deleted element
72	            .reduce<Pick<EventUpdates, 'toUpdate' | 'toLoad'>>(
73	                ({ toUpdate, toLoad }, element) => {
74	                    const existingElement = elementIDs.includes(element.ID || '');
75	
76	                    if (existingElement) {
77	                        toUpdate.push(element);
78	                    } else {
79	                        toLoad.push(element.ID || '');
80	                    }
81	
82	                    return { toUpdate, toLoad };
83	                },
84	                { toUpdate: [], toLoad: [] }
85	            );
86	
87	        void dispatch(eventUpdates({ api, conversationMode, toCreate, toUpdate, toLoad, toDelete }));
88	    });
89	};

