135	export const usePermanentDelete = (labelID: string) => {
136	    const { createNotification } = useNotifications();
137	    const { createModal } = useModals();
138	    const { call } = useEventManager();
139	    const api = useApi();
140	    const getElementsFromIDs = useGetElementsFromIDs();
141	    const optimisticDelete = useOptimisticDelete();
142	
143	    return async (selectedIDs: string[]) => {
144	        const selectedItemsCount = selectedIDs.length;
145	        const draft = labelID === DRAFTS || labelID === ALL_DRAFTS;
146	        const elements = getElementsFromIDs(selectedIDs);
147	        // If the selected item is a conversation, it may contain more than one message.
148	        // We need to know how much messages we want to delete in order to display a specific message if we only delete one of them
149	        const totalMessages = elements.reduce((total, element) => {
150	            return total + (('ContextNumMessages' in element && element.ContextNumMessages) || 0);
151	        }, 0);
152	        const conversationMode = isConversation(elements[0]);
153	        const modalTitle = getDeleteTitle(draft, conversationMode, selectedItemsCount, totalMessages);
154	        const modalText = getModalText(draft, conversationMode, selectedItemsCount, totalMessages);
155	
156	        await new Promise((resolve, reject) => {
157	            createModal(
158	                <ConfirmModal
159	                    title={modalTitle}
160	                    confirm={<ErrorButton type="submit">{c('Action').t`Delete`}</ErrorButton>}
161	                    onConfirm={() => resolve(undefined)}
162	                    onClose={reject}
163	                >
164	                    <Alert className="mb1" type="error">
165	                        {modalText}
166	                    </Alert>
167	                </ConfirmModal>
168	            );
169	        });
170	        const rollback = optimisticDelete(elements, labelID);
171	        try {
172	            const action = conversationMode ? deleteConversations(selectedIDs, labelID) : deleteMessages(selectedIDs);
173	            await api(action);
174	            await call();
175	            const notificationText = getNotificationText(draft, conversationMode, selectedItemsCount, totalMessages);
176	            createNotification({ text: notificationText });
177	        } catch {
178	            rollback();
179	        }
180	    };
181	};
